export const getChapterQuizBank = (chapterId) => QUIZZES[chapterId] || [];

export const chapterHasQuiz = (chapterId) => getChapterQuizBank(chapterId).length > 0;

export const getModuleQuizBank = (module) => {
  if (!module) return [];
  return module.chapters.flatMap((chapter) => getChapterQuizBank(chapter.id));
};

export const moduleHasQuiz = (module) => getModuleQuizBank(module).length > 0;
